import subprocess, shlex

def get_banner(argv0):
    # use bash exec -a
    cmd = f'exec -a {shlex.quote(argv0)} /workspace/./executable -h 2>&1 | head -n 1'
    r = subprocess.run(["bash","-c",cmd], capture_output=True, text=True)
    # r.stdout contains header? Actually banner goes to stderr, but we redirect 2>&1, so stdout contains it
    # find first line with GROMACS -
    for line in r.stdout.splitlines():
        if "GROMACS -" in line:
            return line
    return repr(r.stdout[:200])

for name in ["a","ab","abc","gmx","executable","myprog","verylongprogramname"]:
    banner = get_banner(name)
    print(f"{name!r} -> {banner!r} len={len(banner)} leading={len(banner)-len(banner.lstrip(' '))}")

# Also test for command banners: help and grompp
def get_banner_cmd(argv0, cmd_args):
    # cmd_args like "help" or "grompp -h"
    # we need to pass args after
    quoted = " ".join(shlex.quote(s) for s in cmd_args.split())
    # Actually cmd_args is string, but we want to split
    # Simpler: use subprocess with exec -a and explicit args
    # Use bash: exec -a argv0 /workspace/./executable <args>
    bash_cmd = f'exec -a {shlex.quote(argv0)} /workspace/./executable {cmd_args} 2>&1 | head -n 1'
    r = subprocess.run(["bash","-c",bash_cmd], capture_output=True, text=True)
    for line in r.stdout.splitlines():
        if "GROMACS -" in line:
            return line
    return r.stdout[:200]

for argv0 in ["executable","gmx","a"]:
    for cmd in ["help", "help grompp", "grompp -h", "dump -h"]:
        banner = get_banner_cmd(argv0, cmd)
        print(f"argv0={argv0!r} cmd={cmd!r} -> {banner!r}")

