# But for unknowncmd (global), orig had one blank line before dashes? Let's check:
import subprocess
def raw(args):
    return subprocess.run(["./executable"]+args, capture_output=True).stderr.decode()
for args in [["unknowncmd"], ["-nice","0"], ["grompp","-unknown"], ["grompp"], ["help","commands","extra"]]:
    se = raw(args)
    # Find after command line
    lines = se.splitlines()
    # Find index of command line content
    idx = None
    for i,l in enumerate(lines):
        if l.startswith("  executable") or l.startswith("  gmx") or "executable" in l and "Command line" in lines[i-1]:
            # Actually command line content is next line after "Command line:"
            pass
        if l.strip().startswith("executable") or l.strip().startswith("gmx"):
            # This is the command line content line
            idx = i
    if idx is not None:
        # Check next lines
        snippet = lines[idx:idx+4]
        print(args, snippet, "blank count", sum(1 for l in snippet[1:] if l==""))
        # Also count blanks before dashes
        # Find dashes index
        dash_idx = next((i for i,l in enumerate(lines) if l.startswith("-------------------------------------------------------")), None)
        if dash_idx is not None:
            blanks = dash_idx - idx -1
            print(f"  blanks before dashes: {blanks}")
